// priceCreepsUpData — cut 35's baked calendar page (CRAFT "Bitmaps inside an SVG"). Written by
// scripts/clips/sam-pricing-tokens/bake-calendar.py from the image agent's item 8 (a frontal photo of a real
// monthly wall-calendar page, Unsplash): cut out on its measured rectangle, the printed month, the year and the
// hanger slot painted out with paper. PriceCreepsUp prints each page's own month in ink.
export type CalendarPage = {
  /** data:image/png;base64 URL of the RGBA cut-out, or null (a cream placeholder page) */
  src: string | null;
  /** the PNG's w / h */
  aspect: number;
  /** the paper's top edge, as a fraction of the image height from its top (the bars' slot sits there) */
  topV: number;
  /** where the month prints: left edge (fraction of page width from its left), baseline (fraction of height), cap px */
  label: { x0: number; baseV: number; capPx: number };
};

export const CALENDAR_PAGE: CalendarPage = {
  src: "data:image/png;base64,",
  aspect: 0.708295,
  topV: 0.001082,
  // the month's place: its left edge at the grid's first column (as the photo's printed month), its baseline
  // raised into the cleaned upper paper (0.235 of the height, so the labels can sit just above the caption band)
  label: { x0: 0.1398, baseV: 0.235, capPx: 50 },
};
